python3 -c "
import re,os
root='AlgebraicJacobian.lean'
seen=set(); stack=[]
def mod2path(m): return m.replace('.','/')+'.lean'
for line in open(root):
    m=re.match(r'import\s+(AlgebraicJacobian\S*)',line.strip())
    if m: stack.append(m.group(1))
while stack:
    mod=stack.pop()
    if mod in seen: continue
    seen.add(mod)
    p=mod2path(mod)
    if os.path.exists(p):
        for line in open(p):
            mm=re.match(r'import\s+(AlgebraicJacobian\S*)',line.strip())
            if mm: stack.append(mm.group(1))
disk=set()
for dp,dn,fn in os.walk('AlgebraicJacobian'):
    for f in fn:
        if f.endswith('.lean'): disk.add(os.path.join(dp,f)[:-5].replace('/','.'))
print('on disk:',len(disk),' reachable:',len(seen & disk),' unrooted:',len(disk-seen))
"; sed -n '28,44p' README.md

